import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in, 1 << 16));
        in.nextToken(); int n = (int) in.nval;
        in.nextToken(); int m = (int) in.nval;

        int[][] g = new int[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                in.nextToken();
                g[i][j] = (int) in.nval;
            }

        // A condição (soma ímpar entre vizinhos) obriga um padrão de tabuleiro de xadrez.
        // Só existem duas colorações possíveis:
        //  A: células com (i+j) par devem ter valor par (e (i+j) ímpar → ímpar)
        //  B: o oposto de A
        // Como só podemos ADICIONAR gotas, virar a paridade de uma célula custa no mínimo 1
        // (adicionar 1 gota); manter a paridade custa 0. Logo, o custo de cada coloração é
        // o número de células com paridade "errada", e as duas somam N*M.

        int costA = 0; // custo da coloração A
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                boolean targetOdd = ((i + j) & 1) == 1; // coloração A: (i+j) ímpar -> ímpar
                boolean isOdd = (g[i][j] & 1) == 1;
                if (targetOdd != isOdd) costA++;
            }

        int total = n * m; // N*M é ímpar, logo não há empate entre as duas colorações
        boolean evenClassOdd = 2 * costA > total; // true => usar coloração B ((i+j) par -> ímpar)
        int best = evenClassOdd ? total - costA : costA;

        StringBuilder sb = new StringBuilder();
        sb.append(best).append('\n');
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                boolean targetOdd = evenClassOdd ? ((i + j) & 1) == 0 : ((i + j) & 1) == 1;
                int v = g[i][j];
                if (((v & 1) == 1) != targetOdd) v++; // adiciona 1 gota para corrigir a paridade
                if (j > 0) sb.append(' ');
                sb.append(v);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
